pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount, uint256 lpAmount) public {
        // Bound to realistic non-zero amounts.
        amount = bound(amount, 1, type(uint128).max);
        lpAmount = bound(lpAmount, 1, type(uint128).max);

        // Deploy an adversarial helper that acts as a curated pool.
        MockCuratedPool pool = new MockCuratedPool();

        // Prepare the scenario: transfer some LP tokens to the synth contract to simulate
        // LP collateral already present. This is feasible because C inherits iBEP20 and the
        // mock curated pool is a simple token.
        pool.mint(address(c), lpAmount);

        // Record the initial LPBalance for the pool.
        uint256 initLPBalance = c.mapSynth_LPBalance(address(pool));
        uint256 initLPDebt = c.mapSynth_LPDebt(address(pool));

        // Drive the mutant entry point mintSynth via the adversarial pool.
        vm.prank(address(pool));
        c.mintSynth(address(this), amount);

        // The boundary call, as required by the setup: allowance is a public view function.
        // This call itself does not change state, but we use it as the required entry point.
        try c.allowance(address(this), address(this)) returns (uint256) {
            // Call succeeded; we check invariant.
        } catch {
            // If it reverts, we consider the property vacuously true,
            // but the reference should not revert here.
            assertTrue(false, "allowance should not revert");
        }

        // Property: The difference between mapSynth_LPDebt and mapSynth_LPBalance
        // must remain equal to the amount minted, because the tracked LP balance
        // and debt increase symmetrically. The buggy mintSynth skips _mint, causing
        // a mismatch between recorded debt and actual supply/tracking.
        uint256 postLPBalance = c.mapSynth_LPBalance(address(pool));
        uint256 postLPDebt = c.mapSynth_LPDebt(address(pool));
        // In the correct version, postLPDebt - postLPBalance == initLPDebt - initLPBalance + amount - lpAmount.
        // Since init values are zero, this simplifies to amount - lpAmount.
        // The buggy version has postLPBalance = initLPBalance + lpAmount but no _mint,
        // so the tracking diverges and the invariant breaks.
        assertTrue(postLPDebt - postLPBalance == initLPDebt - initLPBalance);
    }
}

