        // The DEPLOYER is address(this) from setUp, so we can call mintSynth as the deployer (onlyDAO)
        // But mintSynth has modifier onlyPool which checks isCuratedPool(msg.sender)
        // We need to make the pool address be curated. We deploy a helper that acts as curated pool.
        // We'll deploy a mock curated pool and let it call mintSynth via itself.
        MockCuratedPool helper = new MockCuratedPool();
        // The helper will call c.mintSynth when pranked as the helper.
        // But first we need the DAO's POOLFACTORY to return true for isCuratedPool for helper.
        // Since we pass address(this) as BASE and LayerONE, and the DAO interfaces are not deployed,
